package com.sage.business.code.bootstrap;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.nio.file.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.*;
/** Full HTTP verification failure, original repair reserve, isolated Code, new explicit adoption and V6 continuation. */
public class WritableRepairProtocolTest extends WritableCollaborationProtocolTest {
    private final AtomicInteger repairCalls=new AtomicInteger();
    private boolean repairScenario,loseRepairPublication;
    @Override protected boolean repairFixture(){return repairScenario;}
    private boolean repairRequest(JsonNode request){return request.toString().contains("CHILD_WRITE_REPAIR_X")&&!request.path("tools").toString().contains("collaboration_control");}
    @Override protected void observeModelRequest(JsonNode request){if(repairRequest(request))repairCalls.incrementAndGet();else super.observeModelRequest(request);}
    @Override protected ObjectNode replyForModel(JsonNode request){if(!repairRequest(request))return super.replyForModel(request);int n=repairCalls.get();if(n>=3)return mapper.createObjectNode().put("role","assistant").put("content","The isolated repair candidate changes x.txt from broken to v2.");ObjectNode message=mapper.createObjectNode().put("role","assistant"),args=mapper.createObjectNode().put("path","x.txt");if(n==2)args.putArray("edits").addObject().put("oldText","broken").put("newText","v2");message.putArray("tool_calls").addObject().put("id","repair-call-"+n).put("type","function").putObject("function").put("name",n==1?"workspace_read":"workspace_edit").put("arguments",args.toString());return message;}
    @Test public void oneIsolatedRepairUsesOriginalReserveThenRequiresConcreteNewAdoption()throws Exception{repairScenario=true;exercise(false,false);}
    @Test public void originalCompletedRepairReconcilesLostHostPublicationWithoutAnotherModelOrBudget()throws Exception{repairScenario=true;loseRepairPublication=true;exercise(false,false);}
    @Override protected void exerciseRepair(String rid,String group)throws Exception{
        await(()->"NEEDS_ATTENTION".equals(api("GET","/api/v2/runs/"+rid,null,b,null,200).path("sourceStatus").asText()),"Failed verification did not retain the parent; fixture="+root);JsonNode failed=api("GET",group+"/adoptions/adopt-one",null,b,null,200);Assert.assertTrue(failed.toString(),failed.path("contentApplied").asBoolean());Assert.assertFalse(failed.path("verificationPassed").asBoolean());Assert.assertFalse(failed.path("contextCommitted").asBoolean());Path managed=Paths.get(fixtureServices().tasks.observationRun(rid).productWorkspaceRoot);Assert.assertEquals("broken",Files.readString(managed.resolve("x.txt")));Assert.assertEquals(2,parentCallCount());
        JsonNode run=api("GET","/api/v2/runs/"+rid,null,b,null,200);ObjectNode repair=mapper.createObjectNode().put("repairId","repair-one").put("expectedAdoptionRevision",failed.path("revision").asText()).put("expectedRunStateVersion",run.path("stateVersion").asText()).put("expectedExecutionEpoch","1").put("objective","CHILD_WRITE_REPAIR_X: inspect the fixed applied x.txt then replace broken with v2. Produce only an isolated candidate.");api("POST",group+"/adoptions/adopt-one/repairs","repair-one",a,repair,202);
        await(()->{JsonNode view=api("GET",group,null,b,null,200);if(view.path("repairs").size()==0)return false;JsonNode observation=view.path("repairs").get(0);if("FAILED".equals(observation.path("state").asText())||"UNKNOWN".equals(observation.path("state").asText()))Assert.fail("fixture="+root+" repair="+observation);return "CANDIDATE_READY".equals(observation.path("state").asText());},"Repair candidate was not sealed; fixture="+root);Assert.assertEquals(3,repairCalls.get());Assert.assertEquals(2,parentCallCount());Assert.assertEquals("Repair must not change the parent", "broken",Files.readString(managed.resolve("x.txt")));
        assertChildHistory(rid,api("GET",group,null,b,null,200).path("repairs").get(0));
        if(loseRepairPublication){
            JsonNode readyBefore=api("GET",group,null,b,null,200);JsonNode budgetBefore=readyBefore.path("sharedBudget");int callsBefore=modelCalls.get();
            stopService();
            try(java.sql.Connection db=java.sql.DriverManager.getConnection("jdbc:sqlite:"+root.resolve("state/gui-sessions.db"))){
                String payload;try(java.sql.PreparedStatement q=db.prepareStatement("SELECT payload_json FROM writable_collaboration_records WHERE run_id=? AND kind='REPAIR' AND entity_id='repair-one'")){q.setString(1,rid);try(java.sql.ResultSet rows=q.executeQuery()){Assert.assertTrue(rows.next());payload=rows.getString(1);}}
                ObjectNode lost=(ObjectNode)mapper.readTree(payload);String candidateId=lost.path("candidateId").asText();lost.remove("candidateId");lost.remove("candidateFingerprint");
                try(java.sql.PreparedStatement q=db.prepareStatement("UPDATE writable_collaboration_records SET status='RUNNING',payload_json=?,revision=revision+1 WHERE run_id=? AND kind='REPAIR' AND entity_id='repair-one'")){q.setString(1,lost.toString());q.setString(2,rid);Assert.assertEquals(1,q.executeUpdate());}
                try(java.sql.PreparedStatement q=db.prepareStatement("DELETE FROM writable_collaboration_records WHERE run_id=? AND kind='CANDIDATE' AND entity_id=?")){q.setString(1,rid);q.setString(2,candidateId);Assert.assertEquals(1,q.executeUpdate());}
            }
            restartService();JsonNode lost=api("GET",group,null,b,null,200).path("repairs").get(0);Assert.assertEquals("RUNNING",lost.path("state").asText());Assert.assertEquals(callsBefore,modelCalls.get());
            ObjectNode recover=mapper.createObjectNode().put("requestId","recover-original-repair").put("expectedRevision",lost.path("revision").asText());JsonNode recovered=api("POST",group+"/repairs/repair-one/recover","recover-original-repair",a,recover,202);Assert.assertEquals(recovered.toString(),"CANDIDATE_READY",recovered.path("state").asText());Assert.assertEquals(recovered,api("POST",group+"/repairs/repair-one/recover","recover-original-repair",a,recover,202));Assert.assertEquals(callsBefore,modelCalls.get());Assert.assertEquals(budgetBefore,api("GET",group,null,b,null,200).path("sharedBudget"));Assert.assertEquals("broken",Files.readString(managed.resolve("x.txt")));
        }
        JsonNode beforeDuplicate=api("GET",group,null,b,null,200);api("POST",group+"/adoptions/adopt-one/repairs","repair-one",a,repair,202);run=api("GET","/api/v2/runs/"+rid,null,b,null,200);ObjectNode second=repair.deepCopy().put("repairId","repair-two").put("expectedRunStateVersion",run.path("stateVersion").asText());Assert.assertEquals("REPAIR_ALLOWANCE_EXHAUSTED",api("POST",group+"/adoptions/adopt-one/repairs","repair-two",a,second,409).path("code").asText());Assert.assertEquals(beforeDuplicate.path("sharedBudget"),api("GET",group,null,b,null,200).path("sharedBudget"));Assert.assertEquals(3,repairCalls.get());Assert.assertEquals(2,parentCallCount());
        JsonNode ready=api("GET",group,null,b,null,200),candidate=null;for(JsonNode value:ready.path("candidates"))if("repair-one".equals(value.path("repairId").asText()))candidate=value;Assert.assertNotNull(candidate);ObjectNode selection=mapper.createObjectNode().put("selectionId","repair-selection").put("expectedGraphRevision",ready.path("revision").asText()).put("dependencyPolicy","REQUIRE_CLOSURE");selection.putArray("units").addObject().put("unitId",candidate.path("unitId").asText()).put("candidateId",candidate.path("candidateId").asText()).put("candidateFingerprint",candidate.path("candidateFingerprint").asText());JsonNode selected=api("POST",group+"/selections","repair-selection",a,selection,202);ObjectNode preview=mapper.createObjectNode().put("previewId","repair-preview").put("selectionFingerprint",selected.path("selectionFingerprint").asText()).put("mode","STRICT");JsonNode previewed=api("POST",group+"/selections/repair-selection/previews","repair-preview",a,preview,202);Assert.assertEquals(previewed.toString(),"READY",previewed.path("state").asText());Assert.assertEquals("broken",Files.readString(managed.resolve("x.txt")));
        run=api("GET","/api/v2/runs/"+rid,null,b,null,200);ObjectNode adopt=mapper.createObjectNode().put("adoptionId","adopt-repair").put("expectedRunStateVersion",run.path("stateVersion").asText()).put("expectedExecutionEpoch","1").put("selectionId","repair-selection").put("selectionFingerprint",selected.path("selectionFingerprint").asText()).put("previewId","repair-preview").put("previewFingerprint",previewed.path("previewFingerprint").asText()).put("mode","STRICT");JsonNode adopted=api("POST",group+"/adoptions","adopt-repair",a,adopt,202);Assert.assertEquals(adopted.toString(),"ADOPTED",adopted.path("state").asText());Assert.assertTrue(adopted.path("contextCommitted").asBoolean());Assert.assertTrue(adopted.path("verificationPassed").asBoolean());Assert.assertEquals("adopt-one",adopted.path("remediatesAdoptionId").asText());Assert.assertEquals(2,parentCallCount());Assert.assertEquals(3,repairCalls.get());Assert.assertEquals("v2",Files.readString(managed.resolve("x.txt")));Assert.assertEquals("REMEDIATED",api("GET",group+"/adoptions/adopt-one",null,b,null,200).path("state").asText());Assert.assertEquals("ADOPTED",api("GET",group,null,b,null,200).path("state").asText());
        run=api("GET","/api/v2/runs/"+rid,null,b,null,200);Assert.assertEquals("PAUSED_FOR_HUMAN",run.path("sourceStatus").asText());command(rid,"resume-after-repair","RESUME",run.path("stateVersion").asLong(),a);await(()->parentCallCount()==3,"Main did not resume after repair");releaseModel.release();await(()->parentCallCount()==4,"Main did not inspect repaired bytes");releaseModel.release();await(()->"COMPLETED".equals(api("GET","/api/v2/runs/"+rid,null,b,null,200).path("state").asText()),"Main did not complete after repair");Assert.assertEquals(3,repairCalls.get());
    }
}
